#!/bin/sh
# Assemble Pokémon Kanto Squad from the parts in this folder (order matters: later parts use earlier globals).
#   Pokemon Kanto Squad.html  full document
#   dist/index.html           body-only copy for a claude.ai artifact (gitignored)
# Sprites in resources/sprites/ (tools/fetch_sprites.sh) are embedded as base64 so the game is a single file.
set -e
SRC=$(cd "$(dirname "$0")" && pwd)
OUT=$(dirname "$SRC")
mkdir -p "$OUT/dist"
# Pokémon sprites: still PNGs from the owner's pack (resources/sprites/pokemon sprites/front|back), shrunk back to their 96 px
# pixels and cropped by tools/pack_pngs.py into resources/pokemon/front|back; each is a one-frame "animation" for the battle
# drawing (SPR_DATA.a), and the game cuts its menu icons from the fronts. Trainers (trainer sprites/more trainers) are stills.
node -e '
const fs = require("fs"), p = require("path"), d = process.argv[1], meta = JSON.parse(fs.readFileSync(p.join(d, "pokemon", "sprites.json"), "utf8"));
const out = { f: {}, b: {}, i: {}, t: {}, a: { f: {}, b: {} } };
for (const [k, side] of [["f", "front"], ["b", "back"]]) for (const id in meta[side]) {
  out[k][id] = fs.readFileSync(p.join(d, "pokemon", side, id + ".png")).toString("base64");
  const [w, h] = meta[side][id]; out.a[k][id] = [w, h, 1, 0, 100];   // (one frame, shown for a second, over and over)
}
for (const f of fs.readdirSync(p.join(d, "sprites", "trainer sprites", "more trainers")).filter(f => f.endsWith(".png")).sort()) out.t[f.slice(0, -4)] = fs.readFileSync(p.join(d, "sprites", "trainer sprites", "more trainers", f)).toString("base64");
fs.writeFileSync(process.argv[2], "\n// Pokémon sprites (still PNGs, base64) and trainer sprites, generated by build.sh\nconst SPR_DATA = " + JSON.stringify(out) + ";\n");
' "$OUT/resources" "$OUT/dist/sprites.js"
# The parts are listed relative to the project folder (its name has spaces, so $BODY must not hold absolute paths).
cd "$OUT"
# Resources from the owner's packs in resources/: item icons (sprites/items, picked by tools/item_icons.json), a few trainer
# pictures (sprites/trainer sprites, picked by tools/trainer_sprites.json), type labels (types/*.png, cut from icedt's DS-style
# sheet by tools/pack_types.py), Poké Balls (balls/*.png, FireRed/LeafGreen battle balls and an overworld item ball, by tools/pack_balls.py), battle backgrounds (battle/*.png, the FireRed/LeafGreen scenes cut by tools/pack_battlebg.py), your trainer's back in battle (backs/*.png, by tools/pack_backs.py), square type icons (typeicons/*.png, Squid Eevee's Minecraft-style set, same script),
# move category icons (sprites/categories), the home screen's overworld (home/: map scenes, Pokémon and player walk sheets,
# by tools/pack_home.py), the Trainer Card and Gym Badges (card/*.png, from the owner's Trainer Card kit
# by tools/pack_card.py), the chapter backgrounds (areas/*.png, cropped from the owner's area previews by
# tools/pack_areas.py) and cries (cries/*.mp3, from tools/pack_cries.py). Its own <script> ahead of
# a2_core.js, so the icon table there can use it.
node -e '
const fs = require("fs"), b64 = f => fs.readFileSync(f).toString("base64"), out = { item: {}, type: {}, cat: {}, cry: {}, trainer: {}, scene: {}, cutin: {}, area: {}, card: {}, badge: {}, tyic: {}, bb: {}, ball: {}, back: {}, backMeta: null, home: { map: {}, mon: {}, pl: {}, meta: null } };
const map = JSON.parse(fs.readFileSync("tools/item_icons.json", "utf8"));
for (const k in map) if (k !== "_") { const f = "resources/sprites/items/" + map[k]; if (!fs.existsSync(f)) throw new Error("item_icons.json: no " + f); out.item[k] = b64(f); }
const tmap = JSON.parse(fs.readFileSync("tools/trainer_sprites.json", "utf8"));
for (const k in tmap) if (k !== "_") { const f = "resources/sprites/trainer sprites/" + tmap[k]; if (!fs.existsSync(f)) throw new Error("trainer_sprites.json: no " + f); out.trainer[k] = b64(f); }
// the pictures of the player looks, cut from the player sheets (tools/pack_backs.py): these come first
for (const f of fs.readdirSync("resources/players").filter(f => f.endsWith(".png"))) out.trainer[f.slice(0, -4)] = b64("resources/players/" + f);
for (const f of fs.readdirSync("resources/types").filter(f => /\.png$/i.test(f))) out.type[f.slice(0, -4)] = b64("resources/types/" + f);
for (const [k, n] of [["P", "Physical"], ["S", "Special"], ["X", "Status"]]) out.cat[k] = b64("resources/sprites/categories/" + n + ".png");
for (const [k, dir] of [["map", "maps"], ["mon", "mons"], ["pl", "players"]]) for (const f of fs.readdirSync("resources/home/" + dir).filter(f => f.endsWith(".png"))) out.home[k][f.slice(0, -4)] = b64("resources/home/" + dir + "/" + f);
out.home.meta = JSON.parse(fs.readFileSync("resources/home/home.json", "utf8"));
for (const f of fs.readdirSync("resources/balls").filter(f => f.endsWith(".png"))) out.ball[f.slice(0, -4)] = b64("resources/balls/" + f);
for (const f of fs.readdirSync("resources/battle").filter(f => f.endsWith(".png"))) out.bb[f.slice(0, -4)] = b64("resources/battle/" + f);
for (const f of fs.readdirSync("resources/scenes").filter(f => f.endsWith(".png"))) out.scene[f.slice(0, -4)] = b64("resources/scenes/" + f);
for (const f of fs.readdirSync("resources/cutins").filter(f => f.endsWith(".png"))) out.cutin[f.slice(0, -4)] = b64("resources/cutins/" + f);
out.medals = b64("resources/medals/medals.png"); out.emotes = b64("resources/emotes/emotes.png");
out.psfx = Object.fromEntries(fs.readdirSync("resources/showdown/fx").map(f => [f, b64("resources/showdown/fx/" + f)]));
out.slots = b64("resources/slots/slots.png"); out.slotsMeta = JSON.parse(fs.readFileSync("resources/slots/slots.json", "utf8"));
out.hud = b64("resources/hud/hud.png"); out.hudMeta = JSON.parse(fs.readFileSync("resources/hud/hud.json", "utf8"));
for (const f of fs.readdirSync("resources/backs").filter(f => f.endsWith(".png"))) out.back[f.slice(0, -4)] = b64("resources/backs/" + f);
out.backMeta = JSON.parse(fs.readFileSync("resources/backs/backs.json", "utf8"));
out.bbHz = JSON.parse(fs.readFileSync("resources/battle/battle.json", "utf8"));
// move sounds: which file in resources/audio/move sfx each move plays (tools/pack_sfx.py); the sounds themselves stay in the folder
out.msfx = JSON.parse(fs.readFileSync("tools/move_sfx.json", "utf8")); delete out.msfx._;
for (const f of fs.readdirSync("resources/typeicons").filter(f => f.endsWith(".png"))) out.tyic[f.slice(0, -4)] = b64("resources/typeicons/" + f);
for (const f of fs.readdirSync("resources/card").filter(f => f.endsWith(".png"))) out.card[f.slice(0, -4)] = b64("resources/card/" + f);
for (const f of fs.existsSync("resources/badges") ? fs.readdirSync("resources/badges").filter(f => f.endsWith(".png")) : []) out.badge[f.slice(0, -4)] = b64("resources/badges/" + f);   // (the Gym Badges of every region: tools/pack_badges.py)
for (const f of fs.readdirSync("resources/areas").filter(f => f.endsWith(".png"))) out.area[f.slice(0, -4)] = b64("resources/areas/" + f);
for (const f of fs.readdirSync("resources/cries").filter(f => f.endsWith(".mp3")).sort()) out.cry[f.slice(0, -4)] = b64("resources/cries/" + f);
fs.writeFileSync("dist/res.js", "<script>\n// Item icons, trainer pictures, area previews, the Trainer Card, type labels, move categories (base64 PNG) and cries (base64 MP3), generated by build.sh\nconst RES_DATA = " + JSON.stringify(out) + ";\n</script>\n");
'
BODY="dist/res.js dist/teamcfg.js dist/moveworth.js src/a2_core.js src/a3a_dex.js src/a3b_kits.js src/a3c_showdown_text.js dist/sprites.js src/a4_story.js src/a4b_johto.js src/a4c_hoenn.js src/a4d_sinnoh.js src/a4e_unova.js src/a4f_kalos.js src/a4g_alola.js src/a4h_galar.js src/a4i_paldea.js src/a5_sprites.js src/a6_state.js src/a6b_ladder.js src/a6c_lines.js src/a6c2_traits.js src/a6d_safari.js src/a6e_people.js src/a6f_talk.js src/a6g_teams.js src/a6h_build.js src/a6i_servers.js src/a6j_live.js src/a6k_offers.js src/a6l_passes.js src/a6m_lucky.js src/a6n_festivals.js src/a7_engine.js src/a8a_render.js src/a8c_sfx.js src/a8b_battle.js src/a8d_showdown.js src/a8e_showdown_scene.js src/a9a_screens.js src/a9b_screens.js src/a9c_meta.js src/a9d_gameboy.js src/a9e_accounts.js src/a9f_stadium.js src/a9g_demo.js src/a9h_social.js src/a9i_home.js src/a9j_slots.js src/a10_boot.js"
# Trainer teams (roles, archetypes, rules, tiers, modes): config/team_config.json, written by the Team Config page
# ("Pokemon Kanto Squad Team Config.html", tools/teamcfg.js), embedded as TEAM_CONFIG ahead of a2_core.js (a3b_kits.js reads its Item Clause)
node -e '
const fs = require("fs"), f = "config/team_config.json";
if (!fs.existsSync(f)) throw new Error("no " + f + " (the Team Config page writes it; config/team_config.default.json is the original)");
const c = JSON.parse(fs.readFileSync(f, "utf8"));
for (const k of ["roles", "archetypes", "rules", "tiers", "modes"]) if (!c[k]) throw new Error(f + ": no " + k);
for (const A of c.archetypes) for (const S of A.subs) for (const [id] of S.slots) if (!c.roles[id]) throw new Error(f + ": " + A.name + " / " + S.name + " uses a role that is not there: " + id);
fs.writeFileSync("dist/teamcfg.js", "<script>\n// Trainer teams: roles, archetypes, rules, tiers and modes, from config/team_config.json (the Team Config page), embedded by build.sh\nconst TEAM_CONFIG = " + JSON.stringify(c) + ";\n</script>\n");
'
# what moves are worth in top-tier battles (tools/move_worth.js writes tools/move_worth.json), embedded as MOVE_WORTH for the optimizer
node -e '
const fs = require("fs"), f = "tools/move_worth.json", w = fs.existsSync(f) ? JSON.parse(fs.readFileSync(f, "utf8")) : { g: {}, s: {} };
fs.writeFileSync("dist/moveworth.js", "<script>\n// What moves are worth in top-tier battles (tools/move_worth.js), for the optimizer (a6h_build.js), embedded by build.sh\nconst MOVE_WORTH = " + JSON.stringify({ g: w.g || {}, s: w.s || {} }) + ";\n</script>\n");
'
# every part shares one script: a second top-level function with the same name would silently replace the first
DUPS=$(cat $BODY | grep -oE "^(async )?function [A-Za-z0-9_]+" | awk '{print $NF}' | sort | uniq -d)
if [ -n "$DUPS" ]; then echo "duplicate top-level functions: $DUPS"; exit 1; fi
# the same inside the battle engine (makeBattle's own functions, two spaces in): the later one would replace the earlier
EDUPS=$(grep -oE "^  (async )?function [A-Za-z0-9_]+" src/a7_engine.js | awk '{print $NF}' | sort | uniq -d)
if [ -n "$EDUPS" ]; then echo "duplicate functions in the battle engine: $EDUPS"; exit 1; fi
{
  printf '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n'
  printf '<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover, user-scalable=no">\n'
  printf '<meta name="theme-color" content="#e3350d">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n'
  cat src/a1_head.html
  printf '</head>\n<body>\n'
  cat $BODY
  printf '</body>\n</html>\n'
} > dist/game.html
cat src/a1_head.html $BODY > dist/index.html
awk '/<script>/{f=1;next}/<\/script>/{f=0}f' $BODY > dist/check.js
node --check dist/check.js || { echo "syntax check failed: the game file was not replaced"; exit 1; }
echo "syntax ok"
# Only replace the playable file once the build has passed the syntax check.
mv dist/game.html "Pokemon Kanto Squad.html"
wc -c "Pokemon Kanto Squad.html"
# the Move Lab: the same game with a panel to play any move's animation in a 1v1 (tools/fxlab.js)
node tools/build_fxlab.js
# the Team Config page: the same game with the editor for how Trainer teams are made (tools/teamcfg.js); it exports config/team_config.json
node tools/build_teamcfg.js
